// @generated by:gauntlet run:godseye-local-hermes-tools
import { randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AgentsFixture, agentsFixture } from "./helpers/agents-fixture.js";
import { toolsPolicy, toolsSelection } from "./helpers/agents-tools-fixture.js";

describe("real Foundation tool admission without an installed executor", () => {
  let f: AgentsFixture;
  beforeEach(async () => {
    f = await agentsFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });
  const ceiling = () => ({
    toolPolicy: toolsPolicy(),
    limits: {
      maxOutputTokens: 1024,
      timeoutSeconds: 5,
      maxCostMicros: 10000,
      maxTurns: 3,
      maxRequests: 3,
    },
  });

  it("T-AC-761 requires fresh owner authentication to establish a tool ceiling", async () => {
    const actor = {
      ...f.freshOwner(),
      authenticatedAt: new Date(f.clock.now().getTime() - 600000).toISOString(),
    };

    await expect(
      f.infrastructure.agents.createProfile(
        actor,
        { ...f.profileInput, ...ceiling() },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "STEP_UP_REQUIRED" });

    expect((await f.infrastructure.agents.overview(f.freshOwner())).profiles).toHaveLength(0);
  });

  it("T-AC-761 refuses explicit tools before journaling or reserving when execution is unavailable", async () => {
    const profile = await f.create(ceiling());

    await expect(
      f.infrastructure.agents.launch(
        f.freshOwner(),
        {
          profileId: profile.id,
          expectedRevision: profile.revision,
          input: "Use copied fixture data",
          toolGrant: toolsSelection(),
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "CAPABILITY_UNAVAILABLE" });

    expect((await f.infrastructure.agents.overview(f.freshOwner())).tasks).toHaveLength(0);
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(0);
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-761 refuses a task grant that widens the profile tool set", async () => {
    const profile = await f.create(ceiling());
    const grant = toolsSelection(toolsPolicy({ tools: ["godseye_json_validate"] }));

    await expect(
      f.infrastructure.agents.launch(
        f.freshOwner(),
        {
          profileId: profile.id,
          expectedRevision: profile.revision,
          input: "A denied extra tool",
          toolGrant: grant,
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });

    expect((await f.infrastructure.agents.overview(f.freshOwner())).tasks).toHaveLength(0);
  });

  it("T-AC-761 refuses a larger task byte budget before unavailable-runtime evaluation", async () => {
    const profile = await f.create({
      ...ceiling(),
      toolPolicy: toolsPolicy({ maxReadBytes: 100 }),
    });

    await expect(
      f.infrastructure.agents.launch(
        f.freshOwner(),
        {
          profileId: profile.id,
          expectedRevision: profile.revision,
          input: "A denied larger read",
          toolGrant: toolsSelection(),
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "FORBIDDEN" });

    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-772 omission of a task grant retains a no-tools task under a configured ceiling", async () => {
    const profile = await f.create(ceiling());

    const task = await f.launch(profile.id, profile.revision);
    await f.work();

    expect((await f.detail(task.id)).task.state).toBe("succeeded");
    expect(await f.infrastructure.agents.toolsDetail(f.freshOwner(), task.id)).toMatchObject({
      taskId: task.id,
      toolGrant: null,
      state: "disabled",
      calls: [],
    });
    expect(f.provider.submissions).toHaveLength(1);
    expect(f.provider.submissions[0]).not.toHaveProperty("toolGrant");
  });

  it("T-AC-773 keeps the tool journal owner-only even for a same-project service", async () => {
    const profile = await f.create();
    const task = await f.launch(profile.id, profile.revision);
    const service = { id: "fixture-service", kind: "service" as const, projectIds: [f.project.id] };

    await expect(f.infrastructure.agents.toolsDetail(service, task.id)).rejects.toMatchObject({
      code: "FORBIDDEN",
    });
  });

  it("T-AC-772 preserves the configured ceiling when a normal profile edit omits it", async () => {
    const profile = await f.create(ceiling());
    const staleOwner = {
      ...f.freshOwner(),
      authenticatedAt: new Date(f.clock.now().getTime() - 600000).toISOString(),
    };

    const changed = await f.infrastructure.agents.configureProfile(
      staleOwner,
      profile.id,
      {
        expectedRevision: profile.revision,
        expectedProjectRevision: f.project.revision,
        expectedEnvironmentRevision: f.development.revision,
        model: profile.model,
        limits: { ...profile.limits, maxOutputTokens: 512 },
      },
      randomUUID(),
    );

    expect(changed.toolPolicy).toEqual(profile.toolPolicy);
    expect(changed.tools).toEqual(profile.tools);
    expect(changed.limits.maxOutputTokens).toBe(512);
  });

  it("T-AC-772 permits protective ceiling removal without fresh step-up", async () => {
    const profile = await f.create(ceiling());
    const staleOwner = {
      ...f.freshOwner(),
      authenticatedAt: new Date(f.clock.now().getTime() - 600000).toISOString(),
    };

    const changed = await f.infrastructure.agents.configureProfile(
      staleOwner,
      profile.id,
      {
        expectedRevision: profile.revision,
        expectedProjectRevision: f.project.revision,
        expectedEnvironmentRevision: f.development.revision,
        model: profile.model,
        limits: { ...profile.limits, maxRequests: 1, maxTurns: 1 },
        toolPolicy: null,
      },
      randomUUID(),
    );

    expect(changed).not.toHaveProperty("toolPolicy");
    expect(changed.tools).toEqual([]);
    expect(changed.limits).toMatchObject({ maxRequests: 1, maxTurns: 1 });
  });

  it("T-AC-766 refuses task admission after the configured environment becomes held", async () => {
    const profile = await f.create(ceiling());
    await f.store.db
      .update(schema.environments)
      .set({ recoveryHold: true })
      .where(eq(schema.environments.id, f.development.id));

    await expect(
      f.infrastructure.agents.launch(
        f.freshOwner(),
        {
          profileId: profile.id,
          expectedRevision: profile.revision,
          input: "A denied held scope",
          toolGrant: toolsSelection(),
        },
        randomUUID(),
      ),
    ).rejects.toMatchObject({ code: "RECOVERY_HOLD" });

    expect(f.provider.submissions).toHaveLength(0);
  });
});
